  const big = Array.from(deg).filter(d => d >= 129).length;
  let touch = 0;
  for (let e = 0; e < NET.E; e++) if (deg[NET.eu[e]] >= 129 || deg[NET.ev[e]] >= 129) touch++;
  const small = Array.from(deg).filter(d => d <= 2).length;
  const sp = bestPath(A('USH'), A('IKS'));
