  pane.querySelector('.chips').addEventListener('click', ev => { const b = ev.target.closest('[data-i]'); if (b) selectAirport(+b.dataset.i); });
  $('#aPath').addEventListener('click', () => { $('#pf').value = code[i]; $('#pt').value = ''; showTab('path'); $('#pt').focus(); });
