  y += 88;
  const route = /\s(to|-|>)\s/i.test(kb.q.trim()), sug = route ? [] : matches(kb.q, 5);
  if (route) textBlock(ctx, 'Press Find route for the shortest path between these two airports.', x, y, W, 25, 36, VC.muted);
